import { mkdir, readFile, rm, writeFile } from "node:fs/promises";
import path from "node:path";
import { getEnv } from "./env";

/**
 * Where scan images live. Local disk today (the Docker `uploads` volume); an S3-compatible
 * implementation can replace it without touching callers. Keys are always generated by the server.
 */
export interface StorageService {
  put(key: string, data: Uint8Array): Promise<void>;
  read(key: string): Promise<Buffer>;
  remove(key: string): Promise<void>;
}

const SAFE_KEY = /^[a-z0-9][a-z0-9/_.-]*$/i;

export function createLocalStorage(root: string): StorageService {
  const base = path.resolve(root);

  function resolve(key: string): string {
    const full = path.resolve(base, key);
    if (!SAFE_KEY.test(key) || key.includes("..") || !full.startsWith(base + path.sep)) {
      throw new Error(`Refusing unsafe storage key: ${key}`);
    }
    return full;
  }

  return {
    async put(key, data) {
      const full = resolve(key);
      await mkdir(path.dirname(full), { recursive: true });
      await writeFile(full, data, { flag: "wx" }); // never overwrite an existing image
    },
    read: (key) => readFile(resolve(key)),
    remove: (key) => rm(resolve(key), { force: true }),
  };
}

let storage: StorageService | undefined;

export function getStorage(): StorageService {
  storage ??= createLocalStorage(getEnv().UPLOADS_DIR);
  return storage;
}

/**
 * Empties the given top-level folders under the uploads root (`npm run demo:reset`, D-056). Only
 * plain folder names are accepted, so nothing outside the root can be touched.
 */
export async function clearUploadFolders(folders: string[], root = getEnv().UPLOADS_DIR) {
  const base = path.resolve(root);
  for (const folder of folders) {
    if (!/^[a-z0-9_-]+$/i.test(folder)) throw new Error(`Refusing unsafe folder: ${folder}`);
    await rm(path.join(base, folder), { recursive: true, force: true });
  }
}
